  "intuition": "Downweight near-tie comparisons by assigning a nonnegative weight proportional to the objective gap; this emphasizes clearer preference signal while still using all valid pairs for coverage.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_scale = extra.get('gap_scale', 1.0)\n    gap_shift = extra.get('gap_shift', 0.0)\n    weight = (gap + gap_shift).clamp_min(0.0) * gap_scale\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_scale': gap_scale, 'gap_shift': gap_shift})\n"
}

